406: fn adder_with_boolean_values() {
407:     // This is a digital logic circuit called an adder:
408:     // https://en.wikipedia.org/wiki/Adder_(electronics)
409:     let mut reactor = Reactor::new();
410:     let a = reactor.create_input(false);
411:     let b = reactor.create_input(false);
412:     let carry_in = reactor.create_input(false);
413: 
414:     let a_xor_b = reactor
415:         .create_compute(&[CellId::Input(a), CellId::Input(b)], |v| v[0] ^ v[1])
416:         .unwrap();
417:     let sum = reactor
418:         .create_compute(&[CellId::Compute(a_xor_b), CellId::Input(carry_in)], |v| {
419:             v[0] ^ v[1]
420:         })
421:         .unwrap();
422: 
423:     let a_xor_b_and_cin = reactor
424:         .create_compute(&[CellId::Compute(a_xor_b), CellId::Input(carry_in)], |v| {
425:             v[0] && v[1]
426:         })
427:         .unwrap();
428:     let a_and_b = reactor
429:         .create_compute(&[CellId::Input(a), CellId::Input(b)], |v| v[0] && v[1])
430:         .unwrap();
431:     let carry_out = reactor
432:         .create_compute(
433:             &[CellId::Compute(a_xor_b_and_cin), CellId::Compute(a_and_b)],
434:             |v| v[0] || v[1],
435:         )
436:         .unwrap();
437: 
438:     let tests = &[
439:         (false, false, false, false, false),
440:         (false, false, true, false, true),
441:         (false, true, false, false, true),
442:         (false, true, true, true, false),
443:         (true, false, false, false, true),
444:         (true, false, true, true, false),
445:         (true, true, false, true, false),
446:         (true, true, true, true, true),
447:     ];
448: 
449:     for &(aval, bval, cinval, expected_cout, expected_sum) in tests {
450:         assert!(reactor.set_value(a, aval));
451:         assert!(reactor.set_value(b, bval));
452:         assert!(reactor.set_value(carry_in, cinval));
453: 
454:         assert_eq!(reactor.value(CellId::Compute(sum)), Some(expected_sum));
455:         assert_eq!(
456:             reactor.value(CellId::Compute(carry_out)),
457:             Some(expected_cout)
458:         );
459:     }
460: }

