/// and fires `callbacks` whenever its value changes between stable states.
struct ComputeCell<'a, T> {
    dependencies: Vec<CellId>,
    compute_func: Box<dyn Fn(&[T]) -> T>,
    value: T,
    callbacks: Vec<Box<dyn FnMut(T) + 'a>>,
}

