/// and fires `callbacks` whenever its value changes between stable states.
type ComputeFunc<'a, T> = Box<dyn Fn(&[T]) -> T + 'a>;
type Callback<'a, T> = Box<dyn FnMut(T) + 'a>;

struct ComputeCell<'a, T> {
    dependencies: Vec<CellId>,
    compute_func: ComputeFunc<'a, T>,
    value: T,
    // Each slot is either a live callback or a tombstone (`None`) left behind by a removal.
    // Using tombstones instead of shifting keeps every `CallbackId` (a slot index) stable.
    callbacks: Vec<Option<Callback<'a, T>>>,
}

